    \begin{itemize}
        \item[\rm (1)] If $a,b\in\widetilde{H}_{*} (\Omega\Sigma X)$ are primitive, then,  the homomorphism $\langle I,I\rangle_{*}\colon \widetilde{H}_{*} (\Omega\Sigma X)\otimes\widetilde{H}_{*} (\Omega\Sigma X) \rightarrow \widetilde{H}_{*} (\Omega\Sigma X) $  sends $a\otimes b$ to $a b-(-1)^{|a||b|}b a=[a,b].$
