        \item[\rm (3)]   If $x_{1}\in\widetilde{H}_{*} (A_{1})$ and $x_{2}\in\widetilde{H}_{*} (A_{2})$ are primitive, then, 
        the homomorphism $\langle f_{1},f_{2}\rangle_{*}\colon \widetilde{H}_{*} ( A_{1})\otimes\widetilde{H}_{*} ( A_{2}) \rightarrow \widetilde{H}_{*} (\Omega\Sigma X) $  sends $x_{1}\otimes x_{2}$ to $[f_{1*} (x_{1}),f_{2*} (x_{2})].$
    \end{itemize}

